//! # Organizationally Unique Identifiers (OUI) database
//!
//! The database comes in two forms:
//! - [`OuiDbBundled`]: data embedded at compile time (generated by `build.rs`, zero runtime overhead)
//! - [`OuiDbOwned`]: loaded at runtime from data files with self-managed memory (requires the `std` feature)
//!
//! Both are unified under the [`OuiDb`] enum, which provides `lookup` / `iter` / `for_each`
//! and similar APIs. The global entry point [`oui_db`] (returning an owning snapshot handle
//! [`OuiDbRef`]) points to the bundled database by default; a custom (owned) database can be
//! installed/replaced via [`set_oui_db`] (callable multiple times, the latest one wins), or
//! reset back to the bundled database via [`reset_oui_db`].
//!
//! ## Lookup
//! 1. Take the first 3 bytes of the MAC, binary-search the `prefix` column of `oui_24`; on miss return `None`, otherwise read the corresponding `loc`
//! 2. If bit 31 of `loc` is 0, compute offset/length and return `names[offset..offset+length]`
//! 3. If bit 31 is 1 and bit 30 is 0, take `mac[3] & 0xF0` and search `oui_28`
//! 4. If bit 31 is 1 and bit 30 is 1, take `[mac[3], mac[4] & 0xF0]` and search `oui_36`
//!
use alloc::string::String;
#[cfg(feature = "std")]
use alloc::sync::Arc;
use core::fmt::Write;
use core::ops::Deref;

use crate::MacAddress;
use crate::oui_data::OUI_DB_BUNDLED;

#[cfg(feature = "std")]
use arc_swap::ArcSwapOption;

mod bundled;
#[cfg(feature = "std")]
mod owned;

pub use bundled::OuiDbBundled;
#[cfg(feature = "std")]
pub use owned::{OuiDbOwned, OuiDbOwnedError};

pub(crate) use bundled::{OuiSubtable, OuiTable};

const OUI_SUBTABLE: &str = "Ieee Registration Authority";

const OUI_VIRTUAL: [&str; 7] = [
    "VMware",
    "QEMU virtual NIC",
    "Bochs virtual NIC",
    "PearPC virtual NIC",
    "Cooperative Linux virtual NIC",
    "Oracle VirtualBox virtual NIC",
    "OpenStack",
];

/// # Locate an org name or subtable offset
///
/// ## Type 0 - points into the `names` string (bit 31 = 0)
/// ```text
/// bit:  31 | 30 29 ... 11 10 09 08 | 07 06 ... 01 00
///       ──   ─────────────────────   ───────────────
///       0      offset (23 bits)        length
/// ```
///
/// ## Type 1 - points to a subtable offset (bit 31 = 1)
/// ```text
/// bit:  31 | 30 | 29 28 ... 01 00
///       ──   ──   ───────────────
///       1  type    subtable index
/// ```
///
/// * bit 31: 0=names, 1=subtable
///   - bit 31 = 0: offset and length within `names`
///       - bit-30-08: offset (23 bits)
///       - bit-07-00: length (8 bits)
///   - bit 31 = 1: points to a subtable
///       - bit-30: subtable type
///         - 0 points to oui_28
///         - 1 points to oui_36
///       - bit-29-00: subtable index (30 bits)
///
type OuiLoc = u32;

/// Encoding of `OuiEntry::extra_prefix`: the top 2 bits are a type flag (bit-15-14)
/// and the low 12 bits hold the extra value.
///
/// extra value = subtable key >> 4 (shifting away the low 4 zero bits used for
/// nibble alignment), hence:
/// - `0b00`: 24-bit prefix, no extra value
/// - `0b01`: 28-bit prefix, the low 4 bits are the extra nibble
/// - `0b10`: 36-bit prefix, the low 12 bits are the extra value
const EXTRA_NONE: u16 = 0b00 << 14;
const EXTRA_OUI28: u16 = 0b01 << 14;
const EXTRA_OUI36: u16 = 0b10 << 14;

/// Source of entry data: borrows a concrete backend (the entry is valid during the borrow)
pub(crate) enum EntrySource<'a> {
    Bundled(&'a OuiDbBundled),
    #[cfg(feature = "std")]
    OwnedBorrowed(&'a OuiDbOwned),
}

impl EntrySource<'_> {
    fn names(&self) -> &str {
        match self {
            EntrySource::Bundled(b) => b.names(),
            #[cfg(feature = "std")]
            EntrySource::OwnedBorrowed(o) => o.names(),
        }
    }
}

/// Decodes `loc` and returns the slice from `names` (length already validated by
/// `build_entry` / `build_owned_entry`)
fn name_slice(names: &str, loc: OuiLoc) -> &str {
    let offset = ((loc >> 9) & 0x3F_FFFF) as usize;
    let length = (loc & 0x1FF) as usize;
    &names[offset..offset + length]
}

/// Builds the uppercase hex string of the full prefix from `prefix` + `extra_prefix`:
/// - 24-bit: 6 chars, e.g. `"000001"`
/// - 28-bit: 7 chars, e.g. `"000001A"`
/// - 36-bit: 9 chars, e.g. `"000001A2B"`
///
/// The prefix width is determined by the top 2 flag bits of `extra_prefix`.
fn format_prefix_hex(prefix: [u8; 3], extra_prefix: u16) -> String {
    let mut s = String::with_capacity(9);
    for b in prefix {
        let _ = write!(s, "{b:02X}");
    }
    match extra_prefix & (0b11 << 14) {
        EXTRA_OUI28 => {
            let _ = write!(s, "{:X}", extra_prefix & 0x0F);
        }
        EXTRA_OUI36 => {
            let _ = write!(s, "{:03X}", extra_prefix & 0x0FFF);
        }
        _ => {}
    }
    s
}

/// An OUI lookup result entry (borrowing)
///
/// Unrelated to `Deref`: the entry itself holds its data source, so
/// [`name`](OuiEntry::name) / [`country_or_region_code`](OuiEntry::country_or_region_code)
/// are always valid for the entry's lifetime. If you need an entry that does not depend
/// on a database borrow, use [`OuiEntryOwned`].
pub struct OuiEntry<'a> {
    source: EntrySource<'a>,
    /// 24-bit prefix
    pub(crate) prefix: [u8; 3],
    /// extra prefix for oui-28 or oui-36 (top 2 bits type flag, low 12 bits extra value key>>4)
    pub(crate) extra_prefix: u16,
    /// `OuiLoc` encoding pointing into `source.names()`
    loc: OuiLoc,
}

impl<'a> OuiEntry<'a> {
    fn loc_slice(&self) -> &str {
        name_slice(self.source.names(), self.loc)
    }

    /// Returns the uppercase hex string of the full prefix:
    /// - 24-bit: 6 chars, e.g. `"000001"`
    /// - 28-bit: 7 chars, e.g. `"000001A"`
    /// - 36-bit: 9 chars, e.g. `"000001A2B"`
    ///
    /// The prefix width is determined by the top 2 flag bits of `OuiEntry::extra_prefix`.
    pub fn prefix_hex(&self) -> String {
        format_prefix_hex(self.prefix, self.extra_prefix)
    }

    /// Organization/vendor name (without the country/region code prefix)
    ///
    /// When the `address` feature is enabled the stored entry also carries the
    /// `|`-separated registered address; the returned name is truncated at the
    /// first `|`.
    pub fn name(&self) -> &str {
        let name = &self.loc_slice()[2..];
        match name.find('|') {
            Some(i) => &name[..i],
            None => name,
        }
    }

    /// Registered organization address.
    ///
    /// Only available with the `address` feature. Returns `""` when the entry has
    /// no address (e.g. a runtime database loaded from a file without addresses,
    /// or custom entries).
    #[cfg(feature = "address")]
    pub fn address(&self) -> &str {
        match self.loc_slice().split_once('|') {
            Some((_, addr)) => addr,
            None => "",
        }
    }

    /// ISO 3166-1 alpha-2 country/region code
    pub fn country_or_region_code(&self) -> &str {
        &self.loc_slice()[0..2]
    }
}

impl core::fmt::Debug for OuiEntry<'_> {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        let mut debug = f.debug_struct("OuiEntry");
        debug
            .field("prefix", &self.prefix_hex())
            .field("name", &self.name())
            .field("country_or_region_code", &self.country_or_region_code());
        #[cfg(feature = "address")]
        debug.field("address", &self.address());
        debug.finish()
    }
}

/// Serializes with the same field set as `Debug`:
/// `prefix` (hex string), `name`, `country_or_region_code`, and `address`
/// (only when the `address` feature is enabled).
#[cfg(feature = "serde")]
impl serde::Serialize for OuiEntry<'_> {
    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    where
        S: serde::Serializer,
    {
        use serde::ser::SerializeStruct;
        let len = if cfg!(feature = "address") { 4 } else { 3 };
        let mut st = serializer.serialize_struct("OuiEntry", len)?;
        st.serialize_field("prefix", &self.prefix_hex())?;
        st.serialize_field("name", &self.name())?;
        st.serialize_field("country_or_region_code", &self.country_or_region_code())?;
        #[cfg(feature = "address")]
        st.serialize_field("address", &self.address())?;
        st.end()
    }
}

/// Owned entry data source: a `'static` reference for the bundled data, an `Arc` for a runtime database.
#[derive(Clone)]
pub(crate) enum EntrySourceOwned {
    Bundled(&'static OuiDbBundled),
    #[cfg(feature = "std")]
    Owned(Arc<OuiDbOwned>),
}

impl EntrySourceOwned {
    fn names(&self) -> &str {
        match self {
            EntrySourceOwned::Bundled(b) => b.names(),
            #[cfg(feature = "std")]
            EntrySourceOwned::Owned(o) => o.names(),
        }
    }
}

/// An OUI lookup result entry (owned)
///
/// Returned by [`OuiDb::lookup_owned`] / [`OuiDb::lookup_mac_owned`] and
/// [`MacAddress::oui_entry`](crate::MacAddress::oui_entry). It owns its data source
/// (a `'static` reference for the bundled data, an `Arc` for a runtime database), so it
/// remains usable after the [`oui_db`] handle or even the database itself is replaced/dropped.
#[derive(Clone)]
pub struct OuiEntryOwned {
    source: EntrySourceOwned,
    prefix: [u8; 3],
    extra_prefix: u16,
    loc: OuiLoc,
}

impl OuiEntryOwned {
    fn loc_slice(&self) -> &str {
        name_slice(self.source.names(), self.loc)
    }

    /// Organization/vendor name (without the country/region code prefix)
    ///
    /// When the `address` feature is enabled the stored entry also contains the
    /// `|`-separated registered address; the returned name is truncated at the
    /// first `|`.
    pub fn name(&self) -> &str {
        let name = &self.loc_slice()[2..];
        match name.find('|') {
            Some(i) => &name[..i],
            None => name,
        }
    }

    /// Registered organization address.
    ///
    /// Only available with the `address` feature. Returns `""` when the entry has
    /// no address (e.g. a runtime database loaded from a file without addresses,
    /// or custom entries).
    #[cfg(feature = "address")]
    pub fn address(&self) -> &str {
        match self.loc_slice().split_once('|') {
            Some((_, addr)) => addr,
            None => "",
        }
    }

    /// ISO 3166-1 alpha-2 country/region code
    pub fn country_or_region_code(&self) -> &str {
        &self.loc_slice()[0..2]
    }

    /// Returns the uppercase hex string of the full prefix, with the same width as [`OuiEntry::prefix_hex`]
    pub fn prefix_hex(&self) -> String {
        format_prefix_hex(self.prefix, self.extra_prefix)
    }
}

impl core::fmt::Debug for OuiEntryOwned {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        let mut debug = f.debug_struct("OuiEntryOwned");
        debug
            .field("prefix", &self.prefix_hex())
            .field("name", &self.name())
            .field("country_or_region_code", &self.country_or_region_code());
        #[cfg(feature = "address")]
        debug.field("address", &self.address());
        debug.finish()
    }
}

/// Serializes with the same field set as `Debug`:
/// `prefix` (hex string), `name`, `country_or_region_code`, and `address`
/// (only when the `address` feature is enabled).
///
/// This makes an entry directly usable with `serde-wasm-bindgen` /
/// `serde_json` in wasm or FFI contexts without hand-written field mapping.
#[cfg(feature = "serde")]
impl serde::Serialize for OuiEntryOwned {
    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    where
        S: serde::Serializer,
    {
        use serde::ser::SerializeStruct;
        let len = if cfg!(feature = "address") { 4 } else { 3 };
        let mut st = serializer.serialize_struct("OuiEntryOwned", len)?;
        st.serialize_field("prefix", &self.prefix_hex())?;
        st.serialize_field("name", &self.name())?;
        st.serialize_field("country_or_region_code", &self.country_or_region_code())?;
        #[cfg(feature = "address")]
        st.serialize_field("address", &self.address())?;
        st.end()
    }
}

impl core::fmt::Display for OuiEntryOwned {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        write!(
            f,
            "{} {} ({})",
            self.prefix_hex(),
            self.name(),
            self.country_or_region_code()
        )?;
        #[cfg(feature = "address")]
        {
            let address = self.address();
            if !address.is_empty() {
                write!(f, " [{address}]")?;
            }
        }
        Ok(())
    }
}

mod sealed {
    pub trait Sealed {}
}

/// Backend storage access interface (sealed, statically dispatched)
///
/// Implemented once each for [`OuiDbBundled`] / [`OuiDbOwned`], so the lookup/iteration
/// core logic exists in a single copy with no dynamic dispatch.
pub(crate) trait OuiBackend: sealed::Sealed {
    fn names(&self) -> &str;
    fn oui_24_prefix(&self) -> &[[u8; 3]];
    fn oui_24_loc(&self) -> &[OuiLoc];
    fn sub28(&self, i: usize) -> (&[u8], &[OuiLoc]);
    fn sub36(&self, i: usize) -> (&[u16], &[OuiLoc]);

    /// Constructs the source of a lookup result (borrowing `self`)
    fn entry_source(&self) -> EntrySource<'_>;
}

/// Resolved entry location info (prefix + sub-prefix + names locator)
struct Resolved {
    prefix: [u8; 3],
    extra_prefix: u16,
    loc: OuiLoc,
}

/// Lookup core logic (generic monomorphization, shared by Bundled/Owned): resolves to a `Resolved`
fn resolve<B: OuiBackend>(db: &B, mac: [u8; 6]) -> Option<Resolved> {
    let key3 = [mac[0], mac[1], mac[2]];
    let idx = db.oui_24_prefix().binary_search(&key3).ok()?;
    let loc = db.oui_24_loc()[idx];
    let prefix = db.oui_24_prefix()[idx];

    if loc & (1 << 31) == 0 {
        // 24-bit: loc points directly into names
        return Some(Resolved {
            prefix,
            extra_prefix: EXTRA_NONE,
            loc,
        });
    }

    let sub_idx = (loc & 0x3FFF_FFFF) as usize;
    if loc & (1 << 30) == 0 {
        // 28-bit: the extra prefix comes directly from the subtable
        let key4 = mac[3] & 0xF0;
        let (p, sub_loc) = db.sub28(sub_idx);
        let i = p.binary_search(&key4).ok()?;
        Some(Resolved {
            prefix,
            extra_prefix: EXTRA_OUI28 | (p[i] as u16 >> 4),
            loc: sub_loc[i],
        })
    } else {
        // 36-bit: the extra prefix comes directly from the subtable
        let key5 = ((mac[3] as u16) << 8) | ((mac[4] & 0xF0) as u16);
        let (p, sub_loc) = db.sub36(sub_idx);
        let i = p.binary_search(&key5).ok()?;
        Some(Resolved {
            prefix,
            extra_prefix: EXTRA_OUI36 | (p[i] >> 4),
            loc: sub_loc[i],
        })
    }
}

/// Builds an [`OuiEntry`] from `Resolved` + data source (validates the names slice)
fn build_entry(source: EntrySource<'_>, r: Resolved) -> Option<OuiEntry<'_>> {
    let offset = ((r.loc >> 9) & 0x3F_FFFF) as usize;
    let length = (r.loc & 0x1FF) as usize;
    if source.names().get(offset..offset + length)?.len() < 2 {
        return None;
    }
    Some(OuiEntry {
        source,
        prefix: r.prefix,
        extra_prefix: r.extra_prefix,
        loc: r.loc,
    })
}

/// Builds an [`OuiEntryOwned`] from `Resolved` + owned data source (validates the names slice)
fn build_owned_entry(source: EntrySourceOwned, r: Resolved) -> Option<OuiEntryOwned> {
    let offset = ((r.loc >> 9) & 0x3F_FFFF) as usize;
    let length = (r.loc & 0x1FF) as usize;
    if source.names().get(offset..offset + length)?.len() < 2 {
        return None;
    }
    Some(OuiEntryOwned {
        source,
        prefix: r.prefix,
        extra_prefix: r.extra_prefix,
        loc: r.loc,
    })
}

/// Lookup core logic (generic monomorphization, shared by Bundled/Owned)
fn lookup_impl<B: OuiBackend>(db: &B, mac: [u8; 6]) -> Option<OuiEntry<'_>> {
    let r = resolve(db, mac)?;
    build_entry(db.entry_source(), r)
}

/// OUI database: bundled (compile-time) or owned (runtime-loaded)
///
/// The `Owned` variant holds its data behind an `Arc`, so cloning an [`OuiDb`] is cheap
/// (it only bumps a reference count and does not deep-copy the database).
#[derive(Clone, Debug)]
pub enum OuiDb {
    Bundled(OuiDbBundled),
    #[cfg(feature = "std")]
    Owned(Arc<OuiDbOwned>),
}

impl From<OuiDbBundled> for OuiDb {
    fn from(db: OuiDbBundled) -> Self {
        OuiDb::Bundled(db)
    }
}

#[cfg(feature = "std")]
impl From<OuiDbOwned> for OuiDb {
    fn from(db: OuiDbOwned) -> Self {
        OuiDb::Owned(Arc::new(db))
    }
}

impl OuiDb {
    /// Checks if the given OUI name corresponds to a virtual NIC.
    ///
    /// # Arguments
    ///
    /// * `name` - The OUI name to check.
    ///
    /// # Returns
    ///
    /// Returns `true` if the name is a virtual NIC (e.g., QEMU, VirtualBox), otherwise `false`.
    pub fn is_virtual_nic(name: &str) -> bool {
        OUI_VIRTUAL.contains(&name)
    }

    /// Returns the name identifier of the subtable (`oui_28`, `oui_32`, `oui_36`) in the database.
    ///
    /// # Returns
    ///
    /// Returns the subtable name string `"Ieee Registration Authority"`.
    pub fn oui_subtable_name() -> &'static str {
        OUI_SUBTABLE
    }

    /// Data source update time (the bundled data comes from the `# Updated:` file header comment)
    pub fn updated(&self) -> &str {
        match self {
            OuiDb::Bundled(b) => b.updated,
            #[cfg(feature = "std")]
            OuiDb::Owned(o) => &o.updated,
        }
    }

    /// Returns the total size in bytes of the data referenced by this database.
    ///
    /// # Example
    ///
    /// ```
    /// use macaddr_ouidb::oui_db;
    /// let bytes = oui_db().data_size_bytes();
    /// assert!(bytes > 0);
    /// ```
    pub fn data_size_bytes(&self) -> usize {
        match self {
            OuiDb::Bundled(b) => b.data_size_bytes(),
            #[cfg(feature = "std")]
            OuiDb::Owned(o) => o.data_size_bytes(),
        }
    }

    /// Looks up the organization name (OUI vendor information) for a given MAC address.
    ///
    /// # Arguments
    ///
    /// * `mac` - The MAC address as a [`MacAddress`] type.
    ///
    /// # Returns
    ///
    /// Returns `Some(OuiEntry)`, otherwise `None`.
    ///
    /// # Example
    ///
    /// ```
    /// use macaddr_ouidb::*;
    /// let mac = MacAddress::new([0x00, 0x1A, 0x2B, 0x3C, 0x4D, 0x5E]);
    /// let org = oui_db().lookup_mac(mac);
    /// ```
    pub fn lookup_mac(&self, mac: MacAddress) -> Option<OuiEntry<'_>> {
        self.lookup(mac.octets())
    }

    /// Owned-returning counterpart of [`OuiDb::lookup_mac`].
    ///
    /// Returns an [`OuiEntryOwned`] that does not borrow from the database, so it
    /// stays valid after the [`OuiDb`] / [`OuiDbRef`] it came from is dropped.
    ///
    /// # Example
    ///
    /// ```
    /// use macaddr_ouidb::*;
    /// let mac = MacAddress::new([0x00, 0x1A, 0x2B, 0x3C, 0x4D, 0x5E]);
    /// let org = oui_db().lookup_mac_owned(mac);
    /// ```
    pub fn lookup_mac_owned(&self, mac: MacAddress) -> Option<OuiEntryOwned> {
        self.lookup_owned(mac.octets())
    }

    /// Looks up the organization entry for a given MAC address byte array.
    ///
    /// Supports 24-bit, 28-bit, and 36-bit OUI queries.
    ///
    /// # Arguments
    ///
    /// * `mac` - A 6-byte MAC address byte array.
    ///
    /// # Returns
    ///
    /// Returns `Some(OuiEntry)` if found, otherwise `None`.
    pub fn lookup(&self, mac: [u8; 6]) -> Option<OuiEntry<'_>> {
        match self {
            OuiDb::Bundled(b) => lookup_impl(b, mac),
            #[cfg(feature = "std")]
            OuiDb::Owned(o) => lookup_impl(&**o, mac),
        }
    }

    /// Owned-returning counterpart of [`OuiDb::lookup`].
    ///
    /// Returns an [`OuiEntryOwned`] that owns its data source (a `'static`
    /// reference for the bundled database, an `Arc` for a runtime-loaded one),
    /// so it is independent of the database's borrow.
    pub fn lookup_owned(&self, mac: [u8; 6]) -> Option<OuiEntryOwned> {
        let r = resolve(self, mac)?;
        let source = match self {
            OuiDb::Bundled(_) => EntrySourceOwned::Bundled(&OUI_DB_BUNDLED),
            #[cfg(feature = "std")]
            OuiDb::Owned(o) => EntrySourceOwned::Owned(Arc::clone(o)),
        };
        build_owned_entry(source, r)
    }

    /// Returns an iterator over every [`OuiEntry`] in the database.
    ///
    /// # Example
    ///
    /// ```
    /// use macaddr_ouidb::oui_db;
    /// let count = oui_db().iter().count();
    /// assert!(count > 40_000);
    /// ```
    pub fn iter(&self) -> OuiIter<'_> {
        match self {
            OuiDb::Bundled(b) => OuiIter {
                inner: OuiIterInner::Bundled(OuiTableIter::new(b)),
            },
            #[cfg(feature = "std")]
            OuiDb::Owned(o) => OuiIter {
                inner: OuiIterInner::Owned(OuiTableIter::new(&**o)),
            },
        }
    }

    /// Calls the handler `f` for every [`OuiEntry`] in the database (side-effecting form,
    /// equivalent to `for e in db.iter() { f(e) }`).
    ///
    /// # Example
    ///
    /// ```
    /// use macaddr_ouidb::oui_db;
    /// let mut count = 0usize;
    /// oui_db().for_each(|_e| count += 1);
    /// assert_eq!(count, oui_db().iter().count());
    /// ```
    pub fn for_each<'a, F>(&'a self, mut f: F)
    where
        F: FnMut(OuiEntry<'a>),
    {
        for entry in self.iter() {
            f(entry);
        }
    }
}

impl sealed::Sealed for OuiDb {}

impl OuiBackend for OuiDb {
    fn names(&self) -> &str {
        match self {
            OuiDb::Bundled(b) => b.names(),
            #[cfg(feature = "std")]
            OuiDb::Owned(o) => o.names(),
        }
    }

    fn oui_24_prefix(&self) -> &[[u8; 3]] {
        match self {
            OuiDb::Bundled(b) => b.oui_24_prefix(),
            #[cfg(feature = "std")]
            OuiDb::Owned(o) => o.oui_24_prefix(),
        }
    }

    fn oui_24_loc(&self) -> &[OuiLoc] {
        match self {
            OuiDb::Bundled(b) => b.oui_24_loc(),
            #[cfg(feature = "std")]
            OuiDb::Owned(o) => o.oui_24_loc(),
        }
    }

    fn sub28(&self, i: usize) -> (&[u8], &[OuiLoc]) {
        match self {
            OuiDb::Bundled(b) => b.sub28(i),
            #[cfg(feature = "std")]
            OuiDb::Owned(o) => o.sub28(i),
        }
    }

    fn sub36(&self, i: usize) -> (&[u16], &[OuiLoc]) {
        match self {
            OuiDb::Bundled(b) => b.sub36(i),
            #[cfg(feature = "std")]
            OuiDb::Owned(o) => o.sub36(i),
        }
    }

    fn entry_source(&self) -> EntrySource<'_> {
        match self {
            OuiDb::Bundled(b) => EntrySource::Bundled(b),
            #[cfg(feature = "std")]
            OuiDb::Owned(o) => EntrySource::OwnedBorrowed(o),
        }
    }
}

/// Iteration cursor: 24-bit main-table index + current 28/36-bit subtable state
///
/// Stores only indices (without borrowing the underlying data), so the same advance
/// logic can be used for borrowed iteration over an [`OuiDb`]
struct IterPos {
    table_i: usize,
    sub: Option<SubPos>,
}

/// Current subtable position
struct SubPos {
    is36: bool,
    base: [u8; 3],
    sub_idx: usize,
    entry_idx: usize,
}

impl IterPos {
    fn new() -> Self {
        IterPos {
            table_i: 0,
            sub: None,
        }
    }
}

/// Advances iteration by one step and returns the next [`Resolved`]
///
/// Entries whose names slice is invalid (`build_entry` returns `None`) are skipped by
/// the caller; this function only performs positioning.
fn iter_step<B: OuiBackend>(db: &B, pos: &mut IterPos) -> Option<Resolved> {
    loop {
        if let Some(mut sub) = pos.sub.take() {
            let resolved = if sub.is36 {
                let (p, l) = db.sub36(sub.sub_idx);
                (sub.entry_idx < l.len()).then(|| {
                    let i = sub.entry_idx;
                    Resolved {
                        prefix: sub.base,
                        extra_prefix: EXTRA_OUI36 | (p[i] >> 4),
                        loc: l[i],
                    }
                })
            } else {
                let (p, l) = db.sub28(sub.sub_idx);
                (sub.entry_idx < l.len()).then(|| {
                    let i = sub.entry_idx;
                    Resolved {
                        prefix: sub.base,
                        extra_prefix: EXTRA_OUI28 | (p[i] as u16 >> 4),
                        loc: l[i],
                    }
                })
            };
            if let Some(r) = resolved {
                sub.entry_idx += 1;
                pos.sub = Some(sub);
                return Some(r);
            }
            continue;
        }

        if pos.table_i >= db.oui_24_loc().len() {
            return None;
        }
        let idx = pos.table_i;
        pos.table_i += 1;
        let loc = db.oui_24_loc()[idx];
        let base = db.oui_24_prefix()[idx];

        if loc & (1 << 31) == 0 {
            return Some(Resolved {
                prefix: base,
                extra_prefix: EXTRA_NONE,
                loc,
            });
        }
        pos.sub = Some(SubPos {
            is36: loc & (1 << 30) != 0,
            base,
            sub_idx: (loc & 0x3FFF_FFFF) as usize,
            entry_idx: 0,
        });
    }
}

/// Generic iteration implementation (monomorphized, shared by Bundled/Owned)
struct OuiTableIter<'a, B: OuiBackend> {
    db: &'a B,
    pos: IterPos,
}

impl<'a, B: OuiBackend> OuiTableIter<'a, B> {
    fn new(db: &'a B) -> Self {
        OuiTableIter {
            db,
            pos: IterPos::new(),
        }
    }
}

impl<'a, B: OuiBackend> Iterator for OuiTableIter<'a, B> {
    type Item = OuiEntry<'a>;

    fn next(&mut self) -> Option<OuiEntry<'a>> {
        loop {
            let r = iter_step(self.db, &mut self.pos)?;
            if let Some(e) = build_entry(self.db.entry_source(), r) {
                return Some(e);
            }
        }
    }
}
enum OuiIterInner<'a> {
    Bundled(OuiTableIter<'a, OuiDbBundled>),
    #[cfg(feature = "std")]
    Owned(OuiTableIter<'a, OuiDbOwned>),
}

/// Iterator over all [`OuiEntry`] values in an [`OuiDb`].
///
/// Created by [`OuiDb::iter`].
pub struct OuiIter<'a> {
    inner: OuiIterInner<'a>,
}

impl<'a> Iterator for OuiIter<'a> {
    type Item = OuiEntry<'a>;

    fn next(&mut self) -> Option<OuiEntry<'a>> {
        match &mut self.inner {
            OuiIterInner::Bundled(it) => it.next(),
            #[cfg(feature = "std")]
            OuiIterInner::Owned(it) => it.next(),
        }
    }
}

// ===== Global database (single global, bundled by default, installable multiple times, old instances reclaimed) =====

/// Default bundled database (`OuiDb::Bundled` form, used for the `Deref` fallback of [`OuiDbRef`])
static BUNDLED_OUI_DB: OuiDb = OuiDb::Bundled(OUI_DB_BUNDLED);

/// Currently installed custom database; `None` means fall back to the bundled database.
///
/// `ArcSwapOption` performs a lock-free load on the read path and manages instances via
/// reference counting: after `set_oui_db` replaces it, [`OuiDbRef`] values already handed
/// out still hold strong references and keep the old instance alive until they are all
/// dropped, thus automatically reclaiming the old database (no leak).
#[cfg(feature = "std")]
static GLOBAL_DB: ArcSwapOption<OuiDb> = ArcSwapOption::const_empty();

/// Owning handle to the current global OUI database
///
/// Returned by [`oui_db`]. It holds a strong reference to the underlying instance,
/// guaranteeing the database stays alive until drop (even if [`set_oui_db`] /
/// [`reset_oui_db`] is called meanwhile); it delegates to [`OuiDb`] through `Deref`,
/// so [`OuiDb`] lookup/iteration methods can be called directly.
///
/// # Example
///
/// ```
/// use macaddr_ouidb::oui_db;
/// let db = oui_db();
/// assert!(db.data_size_bytes() > 0);
/// ```
#[derive(Clone)]
pub struct OuiDbRef {
    #[cfg(feature = "std")]
    inner: Option<Arc<OuiDb>>,
}

impl OuiDbRef {
    /// Borrows the underlying [`OuiDb`]
    pub fn as_db(&self) -> &OuiDb {
        self
    }
}

impl Deref for OuiDbRef {
    type Target = OuiDb;

    fn deref(&self) -> &OuiDb {
        #[cfg(feature = "std")]
        if let Some(a) = &self.inner {
            return a;
        }
        &BUNDLED_OUI_DB
    }
}

/// Returns a handle to the current global OUI database
///
/// Falls back to the bundled [`OuiDbBundled`] by default; after installation via
/// [`set_oui_db`] it reflects the most recently installed database. The returned
/// [`OuiDbRef`] holds a strong reference to the underlying instance, keeping it valid
/// for the handle's lifetime.
pub fn oui_db() -> OuiDbRef {
    OuiDbRef {
        #[cfg(feature = "std")]
        inner: GLOBAL_DB.load_full(),
    }
}

/// Installs (or replaces) the global OUI database
///
/// - Can be called multiple times: after each call, subsequent [`oui_db`] reads see the latest installed database
/// - Old instances are reclaimed automatically: previously handed-out [`OuiDbRef`] values hold strong references, and the old database is freed as soon as they are all dropped (no leak)
/// - Read operations ([`oui_db`]) never block this function: when nothing is installed it always falls back to the bundled database
///
/// # Example
///
/// ```no_run
/// use macaddr_ouidb::{set_oui_db, OuiDbOwned};
///
/// let owned = OuiDbOwned::from_files("custom-mac-oui.txt", "ieee-mac-oui.txt").unwrap();
/// set_oui_db(owned.into());
///
/// // The database can be replaced again (e.g. hot-reload the data files); the old instance is reclaimed once unreferenced
/// let owned2 = OuiDbOwned::from_files("custom-mac-oui.txt", "ieee-mac-oui.txt").unwrap();
/// set_oui_db(owned2.into());
/// ```
#[cfg(feature = "std")]
pub fn set_oui_db(db: OuiDb) {
    GLOBAL_DB.store(Some(Arc::new(db)));
}

/// Resets the global OUI database back to the bundled library [`OUI_DB_BUNDLED`]
///
/// Equivalent to discarding the database previously installed via [`set_oui_db`]:
/// subsequent [`oui_db`] reads route back to the bundled one. The discarded instance
/// is reclaimed once its references are dropped; callable at any time.
///
/// # Example
///
/// ```no_run
/// use macaddr_ouidb::{reset_oui_db, set_oui_db, OuiDbOwned};
///
/// let owned = OuiDbOwned::from_files("custom-mac-oui.txt", "ieee-mac-oui.txt").unwrap();
/// set_oui_db(owned.into());
/// reset_oui_db(); // back to the bundled database
/// ```
#[cfg(feature = "std")]
pub fn reset_oui_db() {
    GLOBAL_DB.store(None);
}

#[cfg(test)]
mod tests {
    use super::*;
    use alloc::string::ToString;
    use alloc::vec::Vec;

    #[cfg(feature = "serde")]
    #[test]
    fn serde_serialize_matches_debug_fields() {
        let mac = crate::MacAddress::new([0x00, 0x00, 0x01, 0x00, 0x00, 0x00]);
        let db = crate::oui_db();
        let entry = db.lookup_mac(mac).expect("XEROX entry");
        let v = serde_json::to_string(&entry).unwrap();
        assert!(v.contains("\"prefix\":\"000001\""));
        assert!(v.contains("\"country_or_region_code\":\"US\""));
        assert!(v.contains("\"name\":"));
        #[cfg(feature = "address")]
        assert!(v.contains("\"address\":"));

        let owned = crate::oui_db().lookup_mac_owned(mac).expect("XEROX entry");
        let v = serde_json::to_string(&owned).unwrap();
        assert!(v.contains("\"prefix\":\"000001\""));
        assert!(v.contains("\"country_or_region_code\":\"US\""));
    }

    #[test]
    fn prefix_hex_all_widths() {
        let entry = |prefix: [u8; 3], extra_prefix: u16| OuiEntry {
            source: EntrySource::Bundled(&OUI_DB_BUNDLED),
            prefix,
            extra_prefix,
            loc: 0,
        };

        let e24 = entry([0x00, 0x1A, 0x2B], EXTRA_NONE);
        assert_eq!(e24.prefix_hex(), "001A2B");

        let e28 = entry([0x00, 0x1A, 0x2B], EXTRA_OUI28 | 0x0A);
        assert_eq!(e28.prefix_hex(), "001A2BA");

        let e36 = entry([0x00, 0x1A, 0x2B], EXTRA_OUI36 | 0x0AB);
        assert_eq!(e36.prefix_hex(), "001A2B0AB");

        // A high bit in the extra value must not collide with the type flag either
        let e36_hi = entry([0x00, 0x1A, 0x2B], EXTRA_OUI36 | 0xC0D);
        assert_eq!(e36_hi.prefix_hex(), "001A2BC0D");
    }

    #[test]
    fn lookup_returns_oui_entry() {
        let mac = crate::MacAddress::new([0x00, 0x00, 0x01, 0x00, 0x00, 0x00]);
        let db = crate::oui_db();
        let entry = db.lookup_mac(mac).expect("XEROX entry");
        assert_eq!(entry.prefix_hex(), "000001");
        assert_eq!(entry.country_or_region_code(), "US");
        assert!(entry.name().starts_with("XEROX"));
    }

    #[test]
    fn iter_yields_all_entry_widths() {
        let db = &crate::OUI_DB_BUNDLED;
        let mut count = 0usize;
        let (mut c24, mut c28, mut c36) = (0usize, 0usize, 0usize);
        for e in db.iter() {
            count += 1;
            assert_eq!(e.country_or_region_code().len(), 2);
            match e.prefix_hex().len() {
                6 => c24 += 1,
                7 => c28 += 1,
                9 => c36 += 1,
                other => panic!("unexpected prefix length {other}"),
            }
        }

        let expect_24 = db
            .oui_24
            .loc
            .iter()
            .filter(|l| **l & (1 << 31) == 0)
            .count();
        let expect_28: usize = db.oui_28.iter().map(|s| s.loc.len()).sum();
        let expect_36: usize = db.oui_36.iter().map(|s| s.loc.len()).sum();

        assert_eq!(c24, expect_24);
        assert_eq!(c28, expect_28);
        assert_eq!(c36, expect_36);
        assert_eq!(count, expect_24 + expect_28 + expect_36);
    }

    #[test]
    fn iter_and_lookup_roundtrip() {
        let db = crate::oui_db();
        for e in db.iter() {
            let mut mac = [0u8; 6];
            mac[..3].copy_from_slice(&e.prefix);
            match e.extra_prefix & (0b11 << 14) {
                EXTRA_OUI28 => mac[3] = ((e.extra_prefix & 0x0F) as u8) << 4,
                EXTRA_OUI36 => {
                    let v = e.extra_prefix & 0x0FFF;
                    mac[3] = (v >> 4) as u8;
                    mac[4] = ((v & 0x0F) as u8) << 4;
                }
                _ => {}
            }
            let looked = db
                .lookup(mac)
                .unwrap_or_else(|| panic!("lookup failed for {}", e.prefix_hex()));
            assert_eq!(looked.prefix_hex(), e.prefix_hex());
            assert_eq!(looked.name(), e.name());
        }
    }

    #[test]
    fn for_each_visits_every_entry() {
        let mut names: Vec<String> = Vec::new();
        crate::oui_db().for_each(|e| names.push(e.name().to_string()));
        let expect: Vec<String> = crate::oui_db()
            .iter()
            .map(|e| e.name().to_string())
            .collect();
        assert_eq!(names.len(), crate::oui_db().iter().count());
        assert_eq!(names, expect);
    }

    /// The embedded database (names + lookup tables) currently occupies roughly
    /// 1.0 MB with trimmed names, ~1.2 MB with the `fullname` dataset and ~3 MB
    /// with the `address` dataset. This test guards against accidental runaway
    /// growth while tolerating normal data refreshes.
    #[test]
    fn data_size_is_within_expected_range() {
        let db = &crate::OUI_DB_BUNDLED;
        let size = db.data_size_bytes();

        // Always covers at least the name string itself.
        assert!(size >= db.names.len());
        assert!(
            size > 512 * 1024,
            "database unexpectedly small: {size} bytes"
        );
        let upper = if cfg!(feature = "address") {
            8 * 1024 * 1024
        } else {
            2 * 1024 * 1024
        };
        assert!(size < upper, "database unexpectedly large: {size} bytes");
    }

    #[test]
    fn data_size_is_deterministic() {
        let db = crate::oui_db();
        assert_eq!(db.data_size_bytes(), db.data_size_bytes());
    }

    #[cfg(feature = "address")]
    #[test]
    fn address_is_exposed_and_name_is_stripped() {
        let db = &crate::OUI_DB_BUNDLED;

        // An IEEE entry carries a registered address; the name is stripped at '|'
        let entry = db
            .lookup([0x00, 0x00, 0x01, 0x00, 0x00, 0x00])
            .expect("XEROX entry");
        assert!(entry.name().starts_with("XEROX"), "name: {}", entry.name());
        assert!(
            !entry.name().contains('|'),
            "name should be stripped: {}",
            entry.name()
        );
        assert!(
            !entry.address().is_empty(),
            "IEEE entry should carry an address"
        );

        // A custom entry has no address -> empty string
        let custom = db
            .lookup([0x52, 0x54, 0x00, 0x00, 0x00, 0x00])
            .expect("QEMU custom entry");
        assert_eq!(custom.address(), "");
    }

    #[test]
    fn updated_timestamp_is_present() {
        let db = &crate::OUI_DB_BUNDLED;
        // RFC 3339: 2026-10-17T03:14:54Z
        assert!(!db.updated.is_empty());
        assert!(db.updated.ends_with('Z'));
        assert_eq!(db.updated.len(), 20);
    }
}
